private val mutex = Mutex()
private var balance = 0L

suspend fun deposit(amount: Long) = mutex.withLock {
    require(amount > 0)
    balance += amount
}

sealed interface CounterCommand {
    data object Increment : CounterCommand
}

suspend fun consume(commands: ReceiveChannel<CounterCommand>) {
    var value = 0
    for (command in commands) if (command is CounterCommand.Increment) value++
}
